/**
 * Asserts that a value is a valid master viewing key.
 *
 * Validates that the value is a bigint within the BN254 field.
 *
 * @param value - The bigint to assert (must be in range [0, BN254_FIELD_PRIME - 1])
 * @throws {CryptographyAssertionError} If not a bigint, is negative, or exceeds BN254 field prime
 * @returns `void` — narrows the type of `value` to `MasterViewingKey` on success
 *
 * @example
 * ```typescript
 * const mvk = deriveMasterViewingKey(masterSeed);
 * assertMasterViewingKey(mvk);
 * // mvk is now typed as MasterViewingKey
 * ```
 *
 * @public
 */
export function assertMasterViewingKey(value: bigint): asserts value is MasterViewingKey {
  if (typeof value !== "bigint") {
    throw new CryptographyAssertionError(`Expected bigint, got ${typeof value}`, {
      value,
      expectedType: "MasterViewingKey",
    });
  }
  if (value < 0n) {
    throw new CryptographyAssertionError(`Value ${String(value)} is negative`, {
      value,
      expectedType: "MasterViewingKey",
      constraint: "value >= 0",
    });
  }
  if (value >= BN254_FIELD_PRIME) {
    throw new CryptographyAssertionError(`Value exceeds BN254 field prime`, {
      value,
      expectedType: "MasterViewingKey",
      constraint: `value < ${String(BN254_FIELD_PRIME)}`,
    });
  }
}

